func newCaptureDevice() unsafe.Pointer { return unsafe.Pointer(new(capture.CaptureDevice)) }

func newNCaptureDevice(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]capture.CaptureDevice, n)))
}

func ptrCaptureDevice(p unsafe.Pointer, c int32) any {
	r := (*capture.CaptureDevice)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.UserID))
	case 4:
		return &r.Name
	case 5:
		return &r.MachineName
	case 6:
		return &r.WindowsUser
	case 7:
		return &r.AgentVersion
	case 8:
		return (*string)(unsafe.Pointer(&r.Architecture))
	case 9:
		return &r.OSVersion
	case 10:
		return (*string)(unsafe.Pointer(&r.Status))
	case 11:
		return &r.RefreshTokenHash
	case 12:
		return &r.PreviousRefreshHash
	case 13:
		return &r.AccessTokenHash
	case 14:
		return &r.AccessTokenExpiresAt
	case 15:
		return &r.Sources
	case 16:
		return &r.LastSeenAt
	case 17:
		return &r.LastIP
	case 18:
		return &r.RevokedAt
	case 19:
		return (**string)(unsafe.Pointer(&r.RevokedByID))
	case 20:
		return &r.RevokedReason
	case 21:
		return &r.ActiveRoleIDs
	case 22:
		return &r.SessionEpoch
	case 23:
		return &r.Version
	case 24:
		return &r.CreatedAt
	case 25:
		return &r.UpdatedAt
	}
	return nil
}

func valueCaptureDevice(p unsafe.Pointer, c int32) any {
	r := (*capture.CaptureDevice)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.UserID)
	case 4:
		return r.Name
	case 5:
		return r.MachineName
	case 6:
		if r.WindowsUser == "" {
			return nil
		}
		return r.WindowsUser
	case 7:
		return r.AgentVersion
	case 8:
		return string(r.Architecture)
	case 9:
		if r.OSVersion == "" {
			return nil
		}
		return r.OSVersion
	case 10:
		return string(r.Status)
	case 11:
		return r.RefreshTokenHash
	case 12:
		if r.PreviousRefreshHash == "" {
			return nil
		}
		return r.PreviousRefreshHash
	case 13:
		return r.AccessTokenHash
	case 14:
		return r.AccessTokenExpiresAt
	case 15:
		if r.Sources == nil {
			return keel.EmptyJSONArray
		}
		return r.Sources
	case 16:
		if r.LastSeenAt == nil {
			return nil
		}
		return *r.LastSeenAt
	case 17:
		if r.LastIP == "" {
			return nil
		}
		return r.LastIP
	case 18:
		if r.RevokedAt == nil {
			return nil
		}
		return *r.RevokedAt
	case 19:
		if r.RevokedByID == nil {
			return nil
		}
		return string(*r.RevokedByID)
	case 20:
		if r.RevokedReason == "" {
			return nil
		}
		return r.RevokedReason
	case 21:
		if r.ActiveRoleIDs == nil {
			return keel.EmptyJSONArray
		}
		return r.ActiveRoleIDs
	case 22:
		return r.SessionEpoch
	case 23:
		return r.Version
	case 24:
		return r.CreatedAt
	case 25:
		return r.UpdatedAt
	}
	return nil
}

