func newCapturePage() unsafe.Pointer { return unsafe.Pointer(new(capture.CapturePage)) }

func newNCapturePage(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]capture.CapturePage, n)))
}

func ptrCapturePage(p unsafe.Pointer, c int32) any {
	r := (*capture.CapturePage)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.BatchID))
	case 4:
		return (*int64)(unsafe.Pointer(&r.Sequence))
	case 5:
		return (*string)(unsafe.Pointer(&r.Status))
	case 6:
		return &r.StoragePath
	case 7:
		return &r.ChecksumSHA256
	case 8:
		return &r.ByteSize
	case 9:
		return &r.ContentType
	case 10:
		return (*int64)(unsafe.Pointer(&r.WidthPx))
	case 11:
		return (*int64)(unsafe.Pointer(&r.HeightPx))
	case 12:
		return (*int64)(unsafe.Pointer(&r.DPI))
	case 13:
		return (*int64)(unsafe.Pointer(&r.Rotation))
	case 14:
		return &r.ThumbnailPath
	case 15:
		return &r.BlankScore
	case 16:
		return &r.IsSeparator
	case 17:
		return &r.Markers
	case 18:
		return &r.FailureMessage
	case 19:
		return &r.CreatedAt
	case 20:
		return &r.UpdatedAt
	}
	return nil
}

func valueCapturePage(p unsafe.Pointer, c int32) any {
	r := (*capture.CapturePage)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.BatchID)
	case 4:
		return int64(r.Sequence)
	case 5:
		return string(r.Status)
	case 6:
		return r.StoragePath
	case 7:
		return r.ChecksumSHA256
	case 8:
		return r.ByteSize
	case 9:
		return r.ContentType
	case 10:
		return int64(r.WidthPx)
	case 11:
		return int64(r.HeightPx)
	case 12:
		return int64(r.DPI)
	case 13:
		return int64(r.Rotation)
	case 14:
		if r.ThumbnailPath == "" {
			return nil
		}
		return r.ThumbnailPath
	case 15:
		if r.BlankScore == nil {
			return nil
		}
		return *r.BlankScore
	case 16:
		return r.IsSeparator
	case 17:
		return r.Markers
	case 18:
		if r.FailureMessage == "" {
			return nil
		}
		return r.FailureMessage
	case 19:
		return r.CreatedAt
	case 20:
		return r.UpdatedAt
	}
	return nil
}

func beforeCreateCapturePage(ctx context.Context, p unsafe.Pointer) error {
	return (*capture.CapturePage)(p).BeforeCreate(ctx)
}

func init() {
	captureBatchesTable.Relations[0].Target = CapturePagesSchema()
	captureBatchesTable.Relations[1].Target = CaptureItemsSchema()
	captureBatchesTable.Relations[2].Target = CaptureDevicesSchema()
}

// intIs64 fails the build where int is not 64 bits: int fields are read through *int64.
const intIs64 = unsafe.Sizeof(int(0)) - 8

var enumArchitecture = [...]schema.EnumValue{
	{Value: `x64`, Label: `X 64`},
}

var enumBatchStatus = [...]schema.EnumValue{
	{Value: `Receiving`, Label: `Batch Receiving`, Doc: `BatchReceiving is open: pages are still arriving.`},
	{Value: `Sealed`, Label: `Batch Sealed`, Doc: `BatchSealed has every page it said it would and is waiting to be read.`},
	{Value: `Processing`, Label: `Batch Processing`},
	{Value: `Ready`, Label: `Batch Ready`, Doc: `BatchReady has been split into items and is waiting on a person.`},
	{Value: `PartiallyFiled`, Label: `Batch Partially Filed`},
	{Value: `Filed`, Label: `Batch Filed`},
	{Value: `Discarded`, Label: `Batch Discarded`},
	{Value: `Expired`, Label: `Batch Expired`},
	{Value: `Failed`, Label: `Batch Failed`},
}

var enumDeviceStatus = [...]schema.EnumValue{
	{Value: `Active`, Label: `Device Active`},
	{Value: `Revoked`, Label: `Device Revoked`},
}

var enumItemStatus = [...]schema.EnumValue{
	{Value: `Proposed`, Label: `Item Proposed`},
	{Value: `Filing`, Label: `Item Filing`},
	{Value: `Filed`, Label: `Item Filed`},
	{Value: `Discarded`, Label: `Item Discarded`},
	{Value: `Failed`, Label: `Item Failed`},
}

var enumPageStatus = [...]schema.EnumValue{
	{Value: `Received`, Label: `Page Received`},
	{Value: `Processed`, Label: `Page Processed`},
	{Value: `Failed`, Label: `Page Failed`},
}

var enumSource = [...]schema.EnumValue{
	{Value: `Scan`, Label: `Scan`},
	{Value: `Print`, Label: `Print`},
}

var enumSuggestionSource = [...]schema.EnumValue{
	{Value: `CoverSheet`, Label: `Suggestion Cover Sheet`},
	{Value: `Request`, Label: `Suggestion Request`},
	{Value: `Classifier`, Label: `Suggestion Classifier`},
	{Value: `Person`, Label: `Suggestion Person`},
}

